<?php use App\Support\App;App::requireAdmin();$db=App::db();$stats=['users'=>$db->query('SELECT COUNT(*) FROM users')->fetchColumn(),'orders'=>$db->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'processing'=>$db->query("SELECT COUNT(*) FROM orders WHERE status='processing'")->fetchColumn()];$title='Admin';require __DIR__.'/../layouts/head.php';?><main class="p-8 max-w-6xl mx-auto"><h1 class="text-2xl font-semibold">Admin Dashboard</h1><div class="grid md:grid-cols-3 gap-4 mt-6"><?php foreach($stats as $k=>$v):?><div class="saas-card p-5"><p><?=$k?></p><b class="text-2xl"><?=$v?></b></div><?php endforeach?></div><div class="mt-6 flex gap-3"><a class="btn btn-dark" href="/admin/products">Products</a><a class="btn" href="/admin/orders">Orders</a><a class="btn" href="/admin/settings">Settings</a></div></main><?php require __DIR__.'/../layouts/foot.php';?>